<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {harnessApi} from '../runtime-client/api';import type {AppDescriptor,VersionDescriptor} from '../types';const props=defineProps<{appKey:string}>();const emit=defineEmits<{edit:[number]}>();const app=reactive<Partial<AppDescriptor>>({});const versions=ref<VersionDescriptor[]>([]);const starter=`defineApp({\n  page: async () => page({ title: "New App", children: [] }),\n  actions: {}\n});`;const load=async()=>{Object.assign(app,await harnessApi.getApp(props.appKey));versions.value=await harnessApi.listVersions(props.appKey)};const save=async()=>{await harnessApi.updateApp(props.appKey,app);await load()};const draft=async()=>{const v:any=await harnessApi.createVersion(props.appKey,starter);emit('edit',v.id)};const rollback=async(id:number)=>{await harnessApi.rollback(props.appKey,id);await load()};onMounted(load);</script>
<template><main class="harness-admin"><h1>{{app.name}}</h1><form @submit.prevent="save" class="harness-admin-form"><label>Name <input v-model="app.name" required></label><label>Route title <input v-model="app.routeTitle" required></label><label>Description <textarea v-model="app.description"/></label><label>Permission <input v-model="app.requiredPermission"></label><button>Save metadata</button></form><header><h2>Versions</h2><button @click="draft">New draft</button></header><table><thead><tr><th>Version</th><th>Status</th><th>Hash</th><th></th></tr></thead><tbody><tr v-for="v in versions" :key="v.id"><td>v{{v.versionNo}}</td><td>{{v.status}}</td><td><code>{{v.sourceHash||'—'}}</code></td><td><button @click="emit('edit',v.id)">View / edit</button><button v-if="v.status==='SUPERSEDED'" @click="rollback(v.id)">Roll back</button></td></tr></tbody></table></main></template>
